const lessons=[{"sentences":[{"speaker":"A","text":"Hello Sarah because I am going away this weekend I was wondering if you could feed my cat.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.5849166666666665},{"speaker":"B","text":"I would be very happy to help you out while you are away from home.","position":2,"audioStartSeconds":5.784916666666667,"audioEndSeconds":10.055375},{"speaker":"A","text":"That is wonderful news because I always worry about leaving him alone for two whole days.","position":3,"audioStartSeconds":10.255375,"audioEndSeconds":15.771583333333334},{"speaker":"B","text":"You do not need to worry at all when you have a good neighbour to assist you.","position":4,"audioStartSeconds":15.971583333333333,"audioEndSeconds":20.237833333333334},{"speaker":"A","text":"His food is kept inside the kitchen cabinet next to the large refrigerator.","position":5,"audioStartSeconds":20.437833333333334,"audioEndSeconds":25.41208333333333},{"speaker":"B","text":"Should I give him one small bowl in the morning and another one at night?","position":6,"audioStartSeconds":25.612083333333334,"audioEndSeconds":29.916208333333334},{"speaker":"A","text":"Yes exactly because he tends to eat everything quickly if I leave too much out.","position":7,"audioStartSeconds":30.116208333333333,"audioEndSeconds":35.20641666666667},{"speaker":"B","text":"I will also make sure his water bowl is always filled with fresh cold water.","position":8,"audioStartSeconds":35.406416666666665,"audioEndSeconds":40.200208333333336},{"speaker":"A","text":"Thank you so much because he can be quite picky about his drinking water.","position":9,"audioStartSeconds":40.40020833333333,"audioEndSeconds":45.15533333333333},{"speaker":"B","text":"I can drop by twice a day once in the morning and once after work.","position":10,"audioStartSeconds":45.355333333333334,"audioEndSeconds":49.814125},{"speaker":"A","text":"That schedule sounds perfect although he might sleep through most of your visits.","position":11,"audioStartSeconds":50.014125,"audioEndSeconds":54.8595},{"speaker":"B","text":"Does he like playing with any particular toys when he is awake?","position":12,"audioStartSeconds":55.0595,"audioEndSeconds":59.2605},{"speaker":"A","text":"He loves chasing a small red ball if you have a few minutes to spare.","position":13,"audioStartSeconds":59.4605,"audioEndSeconds":63.94504166666667},{"speaker":"B","text":"I will definitely spend some time playing with him after he finishes eating.","position":14,"audioStartSeconds":64.14504166666667,"audioEndSeconds":68.83579166666667},{"speaker":"A","text":"I left the spare house key under the blue flower pot by the front door.","position":15,"audioStartSeconds":69.03579166666667,"audioEndSeconds":73.66229166666666},{"speaker":"B","text":"I will grab the key later today so I can check everything before you leave.","position":16,"audioStartSeconds":73.86229166666666,"audioEndSeconds":78.6035}],"questions":[{"prompt":"Why does speaker A approach speaker B?","options":["To ask for help feeding a cat.","To invite her to a weekend party.","To complain about noisy pets."],"answer":"A","evidenceSentence":1,"evidence":"I was wondering if you could feed my cat","explanation":"Speaker A asks if Sarah can feed the cat while away."},{"prompt":"Where is the cat food kept?","options":["In the garage.","Inside the kitchen cabinet.","On the balcony table."],"answer":"B","evidenceSentence":5,"evidence":"His food is kept inside the kitchen cabinet","explanation":"The food is stored inside the kitchen cabinet next to the refrigerator."},{"prompt":"What does speaker B offer to check besides food?","options":["The mail box.","The window locks.","The water bowl."],"answer":"C","evidenceSentence":8,"evidence":"I will also make sure his water bowl is always filled","explanation":"Speaker B promises to keep the water bowl filled with fresh water."},{"prompt":"How often will speaker B visit the house?","options":["Once a week.","Twice a day.","Three times a day."],"answer":"B","evidenceSentence":10,"evidence":"I can drop by twice a day","explanation":"Speaker B states she will visit twice a day."},{"prompt":"What toy does the cat enjoy playing with?","options":["A small red ball.","A furry mouse.","A plastic feather."],"answer":"A","evidenceSentence":13,"evidence":"He loves chasing a small red ball","explanation":"The cat loves to chase a small red ball."},{"prompt":"What action will speaker B take next?","options":["Call the local vet.","Grab the spare key.","Buy more cat food."],"answer":"B","evidenceSentence":16,"evidence":"I will grab the key later today","explanation":"Speaker B says she will grab the house key later today."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
